package com.collabcase.diagram;
import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.Mockito.*;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.context.ApplicationEventPublisher;import org.springframework.test.util.ReflectionTestUtils;
import com.collabcase.diagram.dto.DiagramRenameRequest;import com.collabcase.project.*;import com.collabcase.project.ProjectAccessService.*;import com.collabcase.project.dto.ProjectRenameRequest;import com.collabcase.project.member.ProjectMemberRepository;
class RenameServiceTests{
 @Test void blankNamesAreRejectedByValidation(){try(var validator=jakarta.validation.Validation.buildDefaultValidatorFactory()){assertThat(validator.getValidator().validate(new ProjectRenameRequest("   "))).isNotEmpty();assertThat(validator.getValidator().validate(new DiagramRenameRequest(""))).isNotEmpty();}}
 @Test void viewerCannotRenameProject(){var access=mock(ProjectAccessService.class);UUID projectId=UUID.randomUUID(),userId=UUID.randomUUID();when(access.requireOwner(projectId,userId)).thenThrow(new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN));var service=new ProjectService(mock(ProjectRepository.class),mock(ProjectMemberRepository.class),access);org.assertj.core.api.Assertions.assertThatThrownBy(()->service.rename(projectId,new ProjectRenameRequest("Nuevo"),userId)).isInstanceOf(org.springframework.web.server.ResponseStatusException.class);}
 @Test void ownerRenamesProject(){var projects=mock(ProjectRepository.class);var access=mock(ProjectAccessService.class);Project project=new Project();ReflectionTestUtils.setField(project,"id",UUID.randomUUID());project.setName("Anterior");when(access.requireOwner(eq(project.getId()),any())).thenReturn(new Access(project,EffectiveRole.OWNER));when(projects.saveAndFlush(project)).thenReturn(project);var service=new ProjectService(projects,mock(ProjectMemberRepository.class),access);assertThat(service.rename(project.getId(),new ProjectRenameRequest("  Nuevo  "),UUID.randomUUID()).name()).isEqualTo("Nuevo");}
 @Test void diagramRenamePreservesNodesAndEdgesAndUpdatesTitle(){var diagrams=mock(DiagramRepository.class);var access=mock(ProjectAccessService.class);var events=mock(ApplicationEventPublisher.class);Project project=new Project();ReflectionTestUtils.setField(project,"id",UUID.randomUUID());Diagram diagram=new Diagram();ReflectionTestUtils.setField(diagram,"id",UUID.randomUUID());diagram.setProject(project);diagram.setName("Anterior");diagram.setType("ClassDiagram");List<Map<String,Object>>nodes=List.of(Map.of("id","n"));List<Map<String,Object>>edges=List.of(Map.of("id","e"));diagram.setModel(new LinkedHashMap<>(Map.of("title","Anterior","nodes",nodes,"edges",edges)));when(diagrams.findById(diagram.getId())).thenReturn(Optional.of(diagram));when(diagrams.saveAndFlush(diagram)).thenReturn(diagram);when(access.requireDiagramEditor(eq(project.getId()),any())).thenReturn(new Access(project,EffectiveRole.EDITOR));var response=new DiagramService(diagrams,access,events).rename(diagram.getId(),new DiagramRenameRequest(" Modelo "),UUID.randomUUID());assertThat(response.name()).isEqualTo("Modelo");assertThat(response.model()).containsEntry("title","Modelo");assertThat(response.model().get("nodes")).isSameAs(nodes);assertThat(response.model().get("edges")).isSameAs(edges);verify(events).publishEvent(any(DiagramRenamedEvent.class));}
}
